javascript_dropdown:
document.addEventListener('DOMContentLoaded', () => {
  const navItems = document.querySelectorAll('#blogger-nav .nav-item');
  let currentDropdown = null;
  let currentDropdownMenu = null;

  navItems.forEach(item => {
    const link = item.querySelector('a');
    if (!link) return;
    const title = link.textContent.trim();

    if (title.startsWith('_')) {
      // É filho: remove o '_', converte para dropdown-item
      link.textContent = title.substring(1).trim();
      link.classList.remove('nav-link');
      link.classList.add('dropdown-item');

      // Cria o <ul> do dropdown na primeira vez
      if (!currentDropdownMenu && currentDropdown) {
        currentDropdownMenu = document.createElement('ul');
        currentDropdownMenu.className = 'dropdown-menu border-0 shadow-sm';
        currentDropdown.appendChild(currentDropdownMenu);
        // Transforma o pai em dropdown
        const parentLink = currentDropdown.querySelector('a');
        parentLink.classList.add('dropdown-toggle');
        parentLink.setAttribute('data-bs-toggle', 'dropdown');
        currentDropdown.classList.add('dropdown');
      }

      if (currentDropdownMenu) {
        const li = document.createElement('li');
        li.appendChild(link);
        currentDropdownMenu.appendChild(li);
        item.remove(); // Remove o nav-item original
      }
    } else {
      // É pai: reset state
      currentDropdown = item;
      currentDropdownMenu = null;
    }
  });
});

css_dropdown:
@media (min-width: 992px) {
  .navbar .dropdown:hover .dropdown-menu {
    display: block;
    margin-top: 0;
    border-radius: 0 0 8px 8px;
    box-shadow: 0 10px 15px rgba(0,0,0,0.1);
  }
}
